<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Banner; use App\Models\Category; use App\Models\Page; use App\Models\Post; use App\Models\TeamMember; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Facades\DB;
class ContentController extends Controller {
 private array $types=['posts'=>Post::class,'pages'=>Page::class,'categories'=>Category::class,'banners'=>Banner::class,'team'=>TeamMember::class];
 private function model(string $type){abort_unless(isset($this->types[$type]),404);return $this->types[$type];}
 public function index(string $type){$model=$this->model($type);$items=$model::latest()->paginate(20);return view('admin.content.index',compact('type','items'));}
 public function create(string $type){$this->model($type);return view('admin.content.form',['type'=>$type,'item'=>new ($this->types[$type])]);}
 public function store(Request $r,string $type){$model=$this->model($type);$data=$this->validated($r,$type);if(isset($data['title']))$data['slug']=$data['slug']??Str::slug($data['title']);if(isset($data['name']))$data['slug']=$data['slug']??Str::slug($data['name']);if(in_array($type,['posts','pages']))$data['author_id']=$r->user()->id;if($r->hasFile('image'))$data['image']=$r->file('image')->store($type,'public');if($r->hasFile('featured_image'))$data['featured_image']=$r->file('featured_image')->store($type,'public');if($r->hasFile('photo'))$data['photo']=$r->file('photo')->store($type,'public');if(($data['status']??null)==='published')$data['published_at']=now();$model::create($data);return redirect()->route('admin.content.index',$type)->with('success',ucfirst($type).' item created.');}
 public function edit(string $type,int $id){$model=$this->model($type);$item=$model::findOrFail($id);return view('admin.content.form',compact('type','item'));}
 public function update(Request $r,string $type,int $id){$model=$this->model($type);$item=$model::findOrFail($id);$data=$this->validated($r,$type,$item->id);if(isset($data['title']))$data['slug']=$data['slug']??Str::slug($data['title']);if(isset($data['name']))$data['slug']=$data['slug']??Str::slug($data['name']);foreach(['image','featured_image','photo'] as $field)if($r->hasFile($field)){if($item->$field)Storage::disk('public')->delete($item->$field);$data[$field]=$r->file($field)->store($type,'public');}if(($data['status']??null)==='published'&&!$item->published_at)$data['published_at']=now();$item->update($data);return redirect()->route('admin.content.index',$type)->with('success',ucfirst($type).' item updated.');}
 public function destroy(string $type,int $id){$model=$this->model($type);$model::findOrFail($id)->delete();return back()->with('success','Item moved to trash.');}
 private function validated(Request $r,string $type,?int $id=null):array{
  $common=['status'=>['sometimes','in:draft,published,archived'],'meta_title'=>['nullable','string','max:255'],'meta_description'=>['nullable','string','max:1000']];
  $rules=match($type){
   'posts'=>['title'=>['required','string','max:255'],'slug'=>['nullable','string','max:255',\Illuminate\Validation\Rule::unique('posts')->ignore($id)],'excerpt'=>['nullable','string'],'content'=>['nullable','string'],'featured_image'=>['nullable','image','max:5120'],'status'=>['required','in:draft,published,archived'],'meta_title'=>$common['meta_title'],'meta_description'=>$common['meta_description']],
   'pages'=>['title'=>['required','string','max:255'],'slug'=>['nullable','string','max:255',\Illuminate\Validation\Rule::unique('pages')->ignore($id)],'content'=>['nullable','string'],'template'=>['required','string','max:80'],'status'=>['required','in:draft,published,archived'],'meta_title'=>$common['meta_title'],'meta_description'=>$common['meta_description']],
   'categories'=>['name'=>['required','string','max:150'],'slug'=>['nullable','string','max:180',\Illuminate\Validation\Rule::unique('categories')->ignore($id)],'description'=>['nullable','string'],'parent_id'=>['nullable','exists:categories,id'],'type'=>['required','in:property,post']],
   'banners'=>['title'=>['required','string','max:255'],'subtitle'=>['nullable','string','max:255'],'description'=>['nullable','string'],'image'=>['nullable','image','max:5120'],'button_text'=>['nullable','string','max:100'],'button_url'=>['nullable','url','max:2048'],'placement'=>['required','string','max:60'],'sort_order'=>['nullable','integer','min:0'],'is_active'=>['sometimes','boolean']],
   'team'=>['name'=>['required','string','max:150'],'designation'=>['nullable','string','max:150'],'bio'=>['nullable','string'],'photo'=>['nullable','image','max:5120'],'email'=>['nullable','email'],'phone'=>['nullable','string','max:30'],'sort_order'=>['nullable','integer','min:0'],'is_active'=>['sometimes','boolean']]
  };return $r->validate($rules);
 }
}